#define main storage_backend_main
#include "can_accel.cpp"
#undef main
#include <algorithm>
#include <cstdint>
uint64_t mixrow(uint64_t row,uint64_t source,uint64_t seed=42){uint64_t x=row^((source+1)*UINT64_C(0x9e3779b97f4a7c15))^seed;x=(x^(x>>30))*UINT64_C(0xbf58476d1ce4e5b9);x=(x^(x>>27))*UINT64_C(0x94d049bb133111eb);return x^(x>>31);}
int main(int argc,char**argv){try{if(argc!=4)throw runtime_error("usage: reference_accel car_hacking|ciciov2024 raw_directory output_directory");string dataset=argv[1],root=argv[2],out=argv[3];bool car=dataset=="car_hacking";if(!car&&dataset!="ciciov2024")throw runtime_error("unknown dataset");vector<string> names=car?vector<string>{"DoS_dataset.csv","Fuzzy_dataset.csv","gear_dataset.csv","RPM_dataset.csv"}:vector<string>{"decimal_DoS.csv","decimal_benign.csv","decimal_spoofing-GAS.csv","decimal_spoofing-RPM.csv","decimal_spoofing-SPEED.csv","decimal_spoofing-STEERING_WHEEL.csv"};vector<string> classes=car?vector<string>{"BENIGN","DOS","FUZZY","GEAR","RPM"}:vector<string>{"BENIGN","DOS","SPOOFING_GAS","SPOOFING_RPM","SPOOFING_SPEED","SPOOFING_STEERING_WHEEL"};unordered_map<string,array<unsigned long long,18>> groups;for(size_t source=0;source<names.size();source++){ifstream in(root+"/"+names[source]);if(!in)throw runtime_error("missing source");string line;if(!car)getline(in,line);uint64_t row=car?0:1;while(getline(in,line)){row++;string key;int label;if(car){Rec r=parse(line,source+1);key=r.key;label=r.label;}else{if(!line.empty()&&line.back()=='\r')line.pop_back();auto f=fields(line);if(f.size()!=12)throw runtime_error("invalid decimal CSV width");key=to_string(number(f[0],10,0x1fffffff));for(int j=1;j<9;j++)key+=","+to_string(number(f[j],10,255));string target=f[11];transform(target.begin(),target.end(),target.begin(),::toupper);if(target=="BENIGN")label=0;else if(target=="DOS")label=1;else if(target=="GAS")label=2;else if(target=="RPM")label=3;else if(target=="SPEED")label=4;else if(target=="STEERING_WHEEL")label=5;else throw runtime_error("unknown CIC class");}auto bucket=mixrow(row,source)%10000;int part=bucket<7000?0:(bucket<8500?1:2);auto it=groups.find(key);if(it==groups.end())it=groups.emplace(key,array<unsigned long long,18>{}).first;it->second[label*3+part]++;}cout<<"Reference scanned "<<names[source]<<endl;}ofstream f(out+"/reference_group_counts.csv");f<<"ID,DATA_0,DATA_1,DATA_2,DATA_3,DATA_4,DATA_5,DATA_6,DATA_7";if(car)f<<",DLC";for(auto c:classes)for(auto p:{"train","validation","test"})f<<","<<c<<"_"<<p;f<<"\n";for(auto &g:groups){f<<g.first;for(size_t j=0;j<classes.size()*3;j++)f<<","<<g.second[j];f<<"\n";}cout<<"Reference groups "<<groups.size()<<endl;return 0;}catch(const exception&e){cerr<<e.what()<<endl;return 2;}}
